import{_ as s,c,o as i,af as l}from"./chunks/framework.BKeRpnBD.js";const n=JSON.parse('{"title":"典籍","description":"易學典籍索引，點擊進入每本書的目錄與正文。","frontmatter":{"title":"典籍","description":"易學典籍索引，點擊進入每本書的目錄與正文。"},"headers":[],"relativePath":"classics/index.md","filePath":"classics/index.md"}'),r={name:"classics/index.md"};function d(_,a,e,h,p,v){return i(),c("div",null,[...a[0]||(a[0]=[l('<h1 id="典籍" tabindex="-1">典籍 <a class="header-anchor" href="#典籍" aria-label="Permalink to “典籍”">​</a></h1><p>這裡整理了已公開的易學典籍。每本書都可以直接進入書目頁面，再從左側目錄切到具體章節閱讀。</p><div class="classics-grid"><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">先秦</p><h2><a href="./zhouyi/">周易</a></h2></div><p class="classic-card__author">周 · 周文王、周公旦</p></div><p class="classic-card__summary">完整版《周易》全文，適合直接從經文原典入手閱讀。</p><div class="classic-card__links"><a href="./zhouyi/">進入書目</a><a href="./zhouyi/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">戰國至漢</p><h2><a href="./yizhuan/">易傳</a></h2></div><p class="classic-card__author">相傳春秋末 · 孔子及弟子</p></div><p class="classic-card__summary">又稱《十翼》，是理解《周易》義理最核心的傳文系統。</p><div class="classic-card__links"><a href="./yizhuan/">進入書目</a><a href="./yizhuan/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">唐</p><h2><a href="./zhengyi/">周易正義</a></h2></div><p class="classic-card__author">唐 · 孔穎達</p></div><p class="classic-card__summary">彙集王弼、韓康伯等舊注，唐代奉命纂修《五經正義》。</p><div class="classic-card__links"><a href="./zhengyi/">進入書目</a><a href="./zhengyi/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">先秦</p><h2><a href="./zixia/">子夏易傳</a></h2></div><p class="classic-card__author">相傳春秋末 · 卜子夏</p></div><p class="classic-card__summary">相傳為卜子夏所傳，真偽雖有爭議，但在易學史上長期流傳並具參考價值。</p><div class="classic-card__links"><a href="./zixia/">進入書目</a><a href="./zixia/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">漢</p><h2><a href="./jingshi/">京氏易傳</a></h2></div><p class="classic-card__author">漢 · 京房</p></div><p class="classic-card__summary">西漢京房易學代表作，六爻象數、納甲飛伏系統的重要源流。</p><div class="classic-card__links"><a href="./jingshi/">進入書目</a><a href="./jingshi/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">唐</p><h2><a href="./jijie/">周易集解</a></h2></div><p class="classic-card__author">唐 · 李鼎祚</p></div><p class="classic-card__summary">廣採漢魏以來諸家易注，保存大量古注，是研讀漢唐易學的重要總彙。</p><div class="classic-card__links"><a href="./jijie/">進入書目</a><a href="./jijie/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">北宋</p><h2><a href="./yichuan/">伊川易傳</a></h2></div><p class="classic-card__author">北宋 · 程頤</p></div><p class="classic-card__summary">程頤說《易》的代表作，是宋代理學易學最核心的經典之一。</p><div class="classic-card__links"><a href="./yichuan/">進入書目</a><a href="./yichuan/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">北宋</p><h2><a href="./hengqu/">橫渠易說</a></h2></div><p class="classic-card__author">北宋 · 張載</p></div><p class="classic-card__summary">張載說易代表作，重義理髮揮，是宋代理學源流中的重要易著。</p><div class="classic-card__links"><a href="./hengqu/">進入書目</a><a href="./hengqu/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">北宋</p><h2><a href="./wengong/">溫公易說</a></h2></div><p class="classic-card__author">北宋 · 司馬光</p></div><p class="classic-card__summary">司馬溫公遺易說，以人事與中正之道釋經，文字簡明穩健。</p><div class="classic-card__links"><a href="./wengong/">進入書目</a><a href="./wengong/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">北宋</p><h2><a href="./kouyi/">周易口義</a></h2></div><p class="classic-card__author">北宋 · 倪天隱述胡瑗說</p></div><p class="classic-card__summary">安定胡氏易學的重要傳本，以義理解經，體現宋初講習《易》學面貌。</p><div class="classic-card__links"><a href="./kouyi/">進入書目</a><a href="./kouyi/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">明</p><h2><a href="./jizhu/">周易集註</a></h2></div><p class="classic-card__author">明 · 來知德</p></div><p class="classic-card__summary">來知德象數易學代表作，體系完整，是明代說《易》的重要大書。</p><div class="classic-card__links"><a href="./jizhu/">進入書目</a><a href="./jizhu/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">清</p><h2><a href="./shangshi/">周易尚氏學</a></h2></div><p class="classic-card__author">清 · 尚秉和</p></div><p class="classic-card__summary">晚清象數易學代表作之一，由卦象解經，併兼及古筮與易象考辨。</p><div class="classic-card__links"><a href="./shangshi/">進入書目</a><a href="./shangshi/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">清</p><h2><a href="./tonglun/">周易通論</a></h2></div><p class="classic-card__author">清 · 李光地</p></div><p class="classic-card__summary">李光地系統綜論《周易》經傳義例，平正通達，是清代義理易學入門書。</p><div class="classic-card__links"><a href="./tonglun/">進入書目</a><a href="./tonglun/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">元</p><h2><a href="./benyi-tongshi/">周易本義通釋</a></h2></div><p class="classic-card__author">元 · 胡炳文</p></div><p class="classic-card__summary">以朱子《本義》為主線，參酌諸家而成，是元代朱子學《易》學代表作。</p><div class="classic-card__links"><a href="./benyi-tongshi/">進入書目</a><a href="./benyi-tongshi/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">元</p><h2><a href="./zuanyan/">易纂言</a></h2></div><p class="classic-card__author">元 · 吳澄</p></div><p class="classic-card__summary">吳澄以古易本重整經傳次序，並附音釋考證，是元代重要《易》學著作。</p><div class="classic-card__links"><a href="./zuanyan/">進入書目</a><a href="./zuanyan/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">近代</p><h2><a href="./hangshi/">杭氏易學</a></h2></div><p class="classic-card__author">近代 · 杭辛齋</p></div><p class="classic-card__summary">杭辛齋象數易學代表作之一，從圖書、卦位、消息等處系統展開。</p><div class="classic-card__links"><a href="./hangshi/">進入書目</a><a href="./hangshi/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">近代日本</p><h2><a href="./takashima/">高島易斷</a></h2></div><p class="classic-card__author">日本明治 · 高島吞象</p></div><p class="classic-card__summary">高島易斷是日本易佔名著，以大量佔例把卦象落到現實決策。</p><div class="classic-card__links"><a href="./takashima/">進入書目</a><a href="./takashima/001">開始閱讀</a></div></article><article class="classic-card"><div class="classic-card__head"><div><p class="classic-card__era">漢學與清代註釋</p><h2><a href="./jiaoyilin/">焦氏易林注</a></h2></div><p class="classic-card__author">漢 · 焦延壽（傳） / 清 · 尚秉和注</p></div><p class="classic-card__summary">以《易林》4096 條詩句為基礎，兼具象數與占筮語料價值。</p><div class="classic-card__links"><a href="./jiaoyilin/">進入書目</a><a href="./jiaoyilin/001">開始閱讀</a></div></article></div>',3)])])}const u=s(r,[["render",d]]);export{n as __pageData,u as default};
